referenceSolutions.javascript:
function expandingPanelsEvenKeyCensus(readings, k) {
  const a=readings; let out=[];
  let l=0,s=0;for(let r=0;r<a.length;r++){s+=a[r];while(l<=r&&s-a[l]>=k)s-=a[l++];out.push(s>=k?r-l+1:0);}
  return out.filter(x=>x%2===0).length;
}

